const admin = String($env.N8N_EMAIL_ADMIN || $env.ADMIN_EMAIL || 'admin@example.local').trim();
const team = String($env.N8N_EMAIL_TEAM || $env.TEAM_EMAILS || '').trim();
const day = new Date().toISOString().split('T')[0];
const tables = [
  String($env.N8N_DB_COSECHAS || 'castuo_prod_cosechas'),
  String($env.N8N_DB_ANALISIS || 'castuo_prod_analisis_diarios'),
];
const informe_html = `<h1>Reporte diario CASTÚO</h1><p>Fecha: ${day}</p><p>Tablas referenciadas: ${tables.join(', ')}</p><p>Enlazar Postgres/Data Table y nodo Gmail/SMTP con credencial.</p>`;
const crypto = require('crypto');
const report_hash = crypto.createHash('sha256').update(informe_html + day).digest('hex');
let gaia = { skipped: true };
const gurl = String($env.N8N_GAIACHAIN_API || '').trim();
const gkey = String($env.N8N_GAIACHAIN_API_KEY || '').trim();
if (gurl && gkey) {
  try {
    const r = await fetch(gurl.replace(/\/$/, ''), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + gkey,
      },
      body: JSON.stringify({ type: 'daily_report', report_hash, day }),
    });
    gaia = { http_status: r.status, text: await r.text() };
  } catch (e) {
    gaia = { error: e.message };
  }
}
return [
  {
    json: {
      to: admin,
      cc: team,
      subject: 'Reporte Diario - CASTÚO-SYSTEM - ' + day,
      informe_html,
      report_hash,
      gaia,
      slack_channel: String($env.N8N_SLACK_ALERTS || '').trim(),
    },
  },
];
